namespace CheckoutPricing.Domain;

public sealed class LoyaltyDiscountPolicy
{
    private const int MaxRatePoints = 10;

    public int PayableCents(int subtotalCents, LoyaltyTier tier)
    {
        var ratePoints = Math.Min(BaseRatePoints(tier) + BonusRatePoints(subtotalCents), MaxRatePoints);
        var discountCents = (int)((long)subtotalCents * ratePoints / 100);
        return subtotalCents - discountCents;
    }

    private static int BaseRatePoints(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Green => 5,
        LoyaltyTier.Gold => 7,
        LoyaltyTier.Platinum => 9,
        _ => throw new ArgumentOutOfRangeException(nameof(tier), tier, null),
    };

    private static int BonusRatePoints(int subtotalCents) => subtotalCents switch
    {
        >= 20_000 => 3,
        >= 5_000 => 1,
        _ => 0,
    };
}
